1	import { execFile } from "node:child_process";
2	import { promisify } from "node:util";
3	import { db } from "./db";
4	import { ovh, ovhApi, ovhConfigured } from "./ovh";
5	import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
6	import { getSettingInt } from "./settings";
7	
8	const execFileP = promisify(execFile);
9	
10	/**
11	 * Is this address already the target of a live DNAT rule on this host? Some
12	 * infrastructure (the shared-hosting node, VM 200) reaches its dedicated IP
13	 * entirely through a whole-IP DNAT rule to an internal address — it has no OVH
14	 * Virtual MAC at all, so the MAC-based check above cannot see it. A real
15	 * incident: this exact IP was one query away from being handed to a game
16	 * server because "no Virtual MAC bound" was mistaken for "free" — it was
17	 * actively carrying production hosting traffic via `iptables -t nat`. Treat
18	 * any address with a live DNAT target as claimed, unconditionally.
19	 */
20	async function hasLiveDnatRule(address: string): Promise<boolean> {
21	  try {
22	    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
23	    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
24	  } catch {
25	    // iptables unreadable (permissions, not present, sandboxed test env) — fail
26	    // closed is wrong here (it would make every sync a no-op); fail to "not
27	    // claimed by this specific check" and rely on the Virtual MAC check plus
28	    // the existing DB row remaining authoritative for anything already tracked.
29	    return false;
30	  }
31	}
32	
33	/**
34	 * What OVH actually bills per additional/failover IPv4 in the pool, in cents.
35	 * Single source of truth for both the IP-pool page's "OVH cost" stat and the
36	 * admin Accounting dashboard's auto-pulled infrastructure expense line — before
37	 * this it existed only as a copy of the same number hardcoded on the IP page.
38	 */
39	export const OVH_IP_UNIT_COST_CENTS = 239;
40	
41	const SERVER = process.env.OVH_SERVER_NAME ?? "ns5002569.ip-51-79-162.net";
42	/**
43	 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
44	 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
45	 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
46	 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
47	 */
48	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);
49	
50	/**
51	 * The monthly dedicated-IP surcharge actually charged, from the admin setting
52	 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
53	 * every order/renewal/display path so they can never disagree.
54	 *
55	 * NORMALISED to a non-negative whole number of cents, exactly as
56	 * `extraDiskPerGbCents` (lib/disk-expand.ts) already does for the other
57	 * admin-priced add-on. `getSettingInt` is a raw `Number()` of whatever string sits
58	 * in the `Setting` row, so it happily returns 2.5 or -500. This value is multiplied
59	 * by the term length straight into `chargeCents` (lib/order.ts orderQuote) and into
60	 * `renewalCharge`, and from there into `debitWallet`, `unit_amount` and an Invoice
61	 * row — every one of which is integer cents. A fractional setting produced a
62	 * fractional charge that failed at Stripe or Prisma AFTER the customer had agreed
63	 * to it; a negative one silently discounted the plan.
64	 */
65	export async function dedicatedIpMonthlyCents(): Promise<number> {
66	  const v = await getSettingInt("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS);
67	  return Math.max(0, Math.round(v));
68	}
69	/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
70	export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);
71	
72	/** OVH failover gateway = the host's /24 gateway (…​.254). */
73	export function ovhGateway(): string {
74	  const ip = process.env.PUBLIC_IP ?? "51.79.162.96";
75	  const parts = ip.split(".");
76	  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
77	}
78	
79	/**
80	 * Pull additional/failover IPv4 addresses routed to our server from OVH and
81	 * upsert them into the pool. The host's own primary IP is never poolable.
82	 */
83	export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
84	  if (SANDBOX) return { imported: 0, total: 0 };
85	  if (!ovhConfigured()) return { imported: 0, total: 0 };
86	  const primary = process.env.PUBLIC_IP;
87	  const blocks: string[] = await ovhApi.ips();
88	  let imported = 0;
89	  for (const block of blocks) {
90	    if (block.includes(":")) continue; // IPv6 handled separately
91	    let info: any;
92	    try {
93	      info = await ovhApi.ipInfo(block);
94	    } catch {
95	      continue;
96	    }
97	    if (info?.routedTo?.serviceName !== SERVER) continue;
98	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
99	    // A /32 block is a single usable IP == the block minus the mask.
100	    const address = block.split("/")[0];
101	    if (address === primary) continue;
102	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
103	    if (!existing) {
104	      // An IP that already has a Virtual MAC bound to it on OVH's side is already
105	      // in active use by SOME VM — possibly one this app never created a Server
106	      // row for (e.g. internal infrastructure provisioned directly via the OVH
107	      // API, like the cold-email relay). A genuinely free IP has no bound MAC
108	      // yet. Importing it as FREE anyway let a real customer server collide with
109	      // an unrelated VM's network identity — never assign an IP that's already
110	      // claimed at the network layer, regardless of whether our DB knows about it.
111	      if (await findVirtualMacForIp(address)) continue;
112	      if (await hasLiveDnatRule(address)) continue;
113	      // Every IP this function imports is, by construction, a spare address
114	      // OVH says is routed to us and not yet claimed at the network layer — the
115	      // pool customer orders draw from. Internal-use IPs (the cold-email relay,
116	      // an owner-operated site, the shared-hosting node) are rare, hand-provisioned
117	      // one-offs marked INTERNAL by an admin after the fact; this sync has no way
118	      // to tell them apart from a genuinely free customer IP and must not try —
119	      // it always imports as CUSTOMER (the schema default, stated here for clarity).
120	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE", purpose: "CUSTOMER" } });
121	      imported++;
122	    }
123	  }
124	  const total = await db.dedicatedIp.count();
125	  return { imported, total };
126	}
127	
128	/** Count of IPs actually available to hand to a customer — same eligibility as
129	 * allocateDedicatedIp's claim query; excludes admin-marked INTERNAL rows. */
130	export async function freeCount(): Promise<number> {
131	  return db.dedicatedIp.count({ where: { status: "FREE", purpose: "CUSTOMER" } });
132	}
133	
134	/**
135	 * The real, live monthly OVH bill for the whole dedicated-IP pool, in cents —
136	 * every pooled IP (free or assigned) costs OVH the same per-IP rate regardless
137	 * of whether a customer is using it. Consumed by the Accounting dashboard as an
138	 * automatic recurring INFRASTRUCTURE expense line so this cost is never
139	 * hand-typed and can never drift from what /admin/ips itself shows.
140	 */
141	export async function dedicatedIpPoolMonthlyCostCents(): Promise<number> {
142	  const total = await db.dedicatedIp.count();
143	  return total * OVH_IP_UNIT_COST_CENTS;
144	}
145	
146	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
147	async function findVirtualMacForIp(address: string): Promise<string | null> {
148	  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
149	  for (const m of macs) {
150	    const ips: string[] = await ovh(
151	      "GET",
152	      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
153	    ).catch(() => []);
154	    if (ips.includes(address)) return m;
155	  }
156	  return null;
157	}
158	
159	/**
160	 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
161	 * Returns the address + virtualMac + gateway, or null if none available.
162	 */
163	export async function allocateDedicatedIp(
164	  serverId: string,
165	  vmid: number
166	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
167	  if (SANDBOX) {
168	    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
169	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
170	  }
171	  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
172	  // server already holds a fully-allocated dedicated IP (ASSIGNED + a bound
173	  // Virtual MAC), return it instead of claiming a second pool IP — re-claiming
174	  // would leak an IP and P2002 on the unique DedicatedIp.serverId.
175	  const mine = await db.dedicatedIp.findUnique({ where: { serverId } });
176	  if (mine && mine.status === "ASSIGNED" && mine.virtualMac) {
177	    return { address: mine.address, virtualMac: mine.virtualMac, gateway: ovhGateway() };
178	  }
179	  if (!ovhConfigured()) return null;
180	  // Atomically claim a FREE ip. Excluding purpose: INTERNAL here is a second,
181	  // independent guard (alongside the sync-time checks above) against ever
182	  // handing an admin-marked internal IP — e.g. the shared-hosting node, which
183	  // can sit with serverId: null and no live-attribute for allocation to see —
184	  // to a customer server.
185	  const claim = await db.$transaction(async (tx) => {
186	    const ip = await tx.dedicatedIp.findFirst({
187	      where: { status: "FREE", purpose: "CUSTOMER" },
188	      orderBy: { createdAt: "asc" },
189	    });
190	    if (!ip) return null;
191	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
192	    return ip;
193	  });
194	  if (!claim) return null;
195	
196	  try {
197	    // Reuse an existing vMAC for this IP if one is already bound; else create one.
198	    let mac = await findVirtualMacForIp(claim.address);
199	    if (!mac) {
200	      // Creation is asynchronous (returns a task) — kick it off then poll.
201	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
202	      for (let i = 0; i < 40 && !mac; i++) {
203	        await new Promise((r) => setTimeout(r, 3000));
204	        mac = await findVirtualMacForIp(claim.address);
205	      }
206	    }
207	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
208	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
209	    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
210	  } catch (e) {
211	    // Roll the claim back to FREE on failure
212	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
213	    throw e;
214	  }
215	}
216	
217	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual MAC). */
218	export async function releaseDedicatedIp(serverId: string): Promise<void> {
219	  if (SANDBOX) return;
220	  const ip = await db.dedicatedIp.findUnique({ where: { serverId } });
221	  if (!ip) return;
222	  if (ovhConfigured() && ip.virtualMac) {
223	    try {
224	      // Remove the IP from the vMAC, then delete the vMAC.
225	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
226	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
227	    } catch {
228	      /* best-effort */
229	    }
230	  }
231	  await db.dedicatedIp.update({
232	    where: { id: ip.id },
233	    data: { status: "FREE", serverId: null, virtualMac: null },
234	  });
235	}
236	
237	/** Set reverse DNS (PTR) for a dedicated IP. */
238	export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
239	  if (!ovhConfigured()) return;
240	  await ovhApi.setReverse(`${address}/32`, address, reverse);
241	  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
242	}
