206	/**
207	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
208	 * well-formed: a half-parsed price would be worse than no price at all, because
209	 * the caller's fallback (re-quote) is at least internally consistent.
210	 */
211	export function parseOrderPrice(raw: unknown): OrderPrice | null {
212	  let obj: unknown = raw;
213	  if (typeof raw === "string") {
214	    try {
215	      obj = JSON.parse(raw);
216	    } catch {
217	      return null;
218	    }
219	  }
220	  if (!obj || typeof obj !== "object") return null;
221	  const { chargeCents, promoPercent, promoName, taxCents, taxRatePercent, taxCountry } =
222	    obj as Record<string, unknown>;
223	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
224	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
225	  if (promoPercent < 0 || promoPercent > 100) return null;
226	  // Tax fields are ADDITIVE and lenient: a session written before Finding 1 (or with a
227	  // malformed tax field) carries none, and the charge path recomputes tax from the
228	  // owner's country — which undertaxes at worst, never overcharges.
229	  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
230	  const tr =
231	    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
232	      ? taxRatePercent
233	      : 0;
234	  return {
235	    chargeCents,
236	    promoPercent,
237	    promoName: typeof promoName === "string" ? promoName : "",
238	    taxCents: tc,
239	    taxRatePercent: tr,
240	    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
241	  };
242	}
