250	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
251	    addonMalware: formData.get("addon_malware") === "1",
252	    addonBackup: formData.get("addon_backup") === "1",
253	    addonDocker: formData.get("addon_docker") === "1",
254	    termMonths: Number(formData.get("termMonths") ?? 1),
255	    dedicatedIp: formData.get("dedicatedIp") === "1",
